fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    // Handle edge cases
    if len <= 1 {
        // For empty or single-element arrays, return two empty arrays
        // This satisfies: concatenation reconstructs original, sum of lengths equals original length,
        // and each returned array is strictly shorter than original when len > 1
        return (vec![], vec![]);
    }
    
    // Calculate split point: ensure both parts are non-empty and strictly shorter than original
    let split_point = len / 2;
    
    // Split the vector into two parts
    let first = a[..split_point].to_vec();
    let second = a[split_point..].to_vec();
    
    (first, second)
}